621	                let mut last_ignore: std::collections::HashMap<String, bool> = std::collections::HashMap::new();
622	                let mut flip_logs: u32 = 0;
623	                let mut last_saved = read_pet_positions();
624	                let mut tick: u32 = 0;
625	                loop {
626	                    // 60ms (≈16Hz): click-through detection doesn't need 33Hz
627	                    // polling. The cursor rarely traverses a pet's opaque rect
628	                    // in <60ms, and halving the tick rate halves the Win32
629	                    // GetCursorPos + GetWindowRect calls per second.
630	                    std::thread::sleep(Duration::from_millis(60));
631	
632	                    // Snapshot all pet windows once per tick so spawns/closes
633	                    // during the loop don't corrupt the iterator.
634	                    let wins: Vec<(String, tauri::WebviewWindow)> = handle
635	                        .webview_windows()
636	                        .into_iter()
637	                        .filter(|(label, _)| is_pet_window(label))
638	                        .collect();
639	                    // Classify visibility once per window. Hidden overlays do
640	                    // no work; an unknown state stays interactive until a later
641	                    // poll can classify it safely.
642	                    let mut visible_wins = Vec::new();
643	                    let mut unknown_visibility_wins = Vec::new();
644	                    for window in &wins {
645	                        match window.1.is_visible() {
646	                            Ok(true) => visible_wins.push(window),
647	                            Ok(false) => {}
648	                            Err(_) => unknown_visibility_wins.push(window),
649	                        }
650	                    }
651	                    for (label, win) in &unknown_visibility_wins {
652	                        apply_ignore_state(&mut last_ignore, label, false, |ignore| {
653	                            win.set_ignore_cursor_events(ignore)
654	                        });
655	                    }
656	                    let cur = if visible_wins.is_empty() {
657	                        None
658	                    } else {
659	                        handle.cursor_position().ok()
660	                    };
661	
662	                    // Snapshot all hit rects in ONE lock acquisition (instead of
663	                    // N locks per tick). The clone is ~12 entries × 32 bytes.
664	                    let rects: HitRectMap = handle
665	                        .try_state::<Mutex<HitRectMap>>()
666	                        .and_then(|s| s.lock().ok().map(|m| m.clone()))
667	                        .unwrap_or_default();
668	
669	                    for (label, win) in &visible_wins {
670	                        let Ok(wp) = win.outer_position() else { continue };
671	                        // Fail-safe: no rect yet (webview still booting) or
672	                        // cursor unreadable → keep INTERACTIVE.
673	                        let inside = match &cur {
674	                            Some(cur) => match rects.get(label) {
675	                                Some(r) if r.w > 0.0 => {
676	                                    let rx = cur.x - wp.x as f64;
677	                                    let ry = cur.y - wp.y as f64;
678	                                    rx >= r.x && rx <= r.x + r.w && ry >= r.y && ry <= r.y + r.h
679	                                }
680	                                _ => true, // no rect yet → stay interactive
681	                            },
682	                            None => true,
683	                        };
684	                        // ignore_cursor_events = true → clicks pass through.
685	                        let ignore = !inside;
686	                        if apply_ignore_state(&mut last_ignore, label, ignore, |ignore| {
687	                            win.set_ignore_cursor_events(ignore)
688	                        }) {
689	                            if flip_logs < 60 {
690	                                flip_logs += 1;
691	                                let cur_str = cur.as_ref().map_or("err".to_string(), |c| format!("({:.0},{:.0})", c.x, c.y));
692	                                dlog(&format!(
693	                                    "hit flip: label={label} ignore={ignore} cur={cur_str} win=({},{})",
694	                                    wp.x, wp.y
695	                                ));
696	                            }
697	                        }
698	                    }
699	
700	                    // Prune closed windows and persist every instance position,
701	                    // both throttled to roughly once per second.
702	                    tick = tick.wrapping_add(1);
703	                    if tick % 17 == 0 {
704	                        let active: std::collections::HashSet<&String> =
705	                            wins.iter().map(|(label, _)| label).collect();
706	                        if let Some(state) = handle.try_state::<Mutex<HitRectMap>>() {
707	                            if let Ok(mut rects) = state.lock() {
708	                                rects.retain(|label, _| active.contains(label));
709	                            }
710	                        }
711	                        last_ignore.retain(|label, _| active.contains(label));
712	
713	                        let mut changed = false;
714	                        for (label, window) in &visible_wins {
715	                            let Some(id) = label.strip_prefix(PET_WINDOW_PREFIX) else { continue };
716	                            let Ok(position) = window.outer_position() else { continue };
717	                            let next = (position.x, position.y);
718	                            if last_saved.get(id) != Some(&next) {
719	                                last_saved.insert(id.to_owned(), next);
720	                                changed = true;
721	                            }
722	                        }
723	                        if changed {
724	                            if let Some(state) = handle.try_state::<Mutex<PetPositionMap>>() {
725	                                if let Ok(mut positions) = state.lock() {
726	                                    *positions = last_saved.clone();
727	                                    write_pet_positions(&positions);
728	                                }
729	                            }
730	                        }
731	                    }
732	                }
733	            });
734	
